const cp = require("node:child_process"), fs = require("node:fs"), os = require("node:os"), path = require("node:path");
const r = cp.spawnSync("cmake", ["--version"], { encoding: "utf8", timeout: 30000 });
if (r.status !== 0) throw new Error("cmake 起不来: status=" + r.status + " stderr=" + (r.stderr||"").slice(0,200));
const D = fs.mkdtempSync(path.join(os.tmpdir(), "lobos-cmake-"));
try {
  const CML = [
    "cmake_minimum_required(VERSION 3.13)",
    "project(lobos_cmake_probe LANGUAGES NONE)",
    "add_custom_command(OUTPUT probe.ok",
    "  COMMAND ${CMAKE_COMMAND} -E touch probe.ok)",
    "add_custom_target(probe ALL DEPENDS probe.ok)",
  ].join("\n");
  fs.writeFileSync(path.join(D, "CMakeLists.txt"), CML);
  const c = cp.spawnSync("cmake", ["-S", ".", "-B", "build"], { cwd: D, encoding: "utf8", timeout: 120000 });
  if (c.status !== 0) {
    throw new Error("cmake configure 失败（这通常就是模块目录不在旁边 —— 空壳 cmake 的典型症状）: "
      + ((c.stderr || c.stdout || "").slice(0, 400)));
  }
  if (!fs.existsSync(path.join(D, "build", "CMakeCache.txt")))
    throw new Error("cmake 报成功但没生成 build/CMakeCache.txt —— 它没真 configure");
  const b = cp.spawnSync("cmake", ["--build", "build"], { cwd: D, encoding: "utf8", timeout: 120000 });
  if (b.status !== 0) throw new Error("cmake --build 失败: " + ((b.stderr||b.stdout||"").slice(0,300)));
  if (!fs.existsSync(path.join(D, "probe.ok")))
    throw new Error("build 报成功但 probe.ok 不在 —— add_custom_command 没生效");
  console.log("cmake ok: configure + build 一个真实项目并产出了自定义目标");
} finally {
  fs.rmSync(D, { recursive: true, force: true });
}

