const cp = require('node:child_process'), fs = require('node:fs'), os = require('node:os'), path = require('node:path');

// ① 版本：确认是设备上这个 clang，而不是宿主 PATH 里的同名命令
const r = cp.spawnSync("clang", ["--version"], { encoding: "utf8", timeout: 30000 });
if (r.status !== 0) throw new Error("clang 起不来: status=" + r.status + " stderr=" + (r.stderr||"").slice(0,200));
const ver = (r.stdout || "").trim();
if (ver.indexOf("clang version") < 0) throw new Error("clang --version 的输出不像 clang: " + ver.slice(0,120));

// ② sysroot：从入口拿路径（sysroot 件提供 bin/sysroot，自问自答）
const s = cp.spawnSync("sysroot", [], { encoding: "utf8", timeout: 30000 });
if (s.status !== 0) throw new Error("sysroot 入口起不来 —— 没有它就没法验 clang 能否找头文件");
const SR = (s.stdout || "").trim();
if (!SR || !fs.existsSync(SR)) throw new Error("sysroot 入口打印的路径不存在: " + JSON.stringify(SR));
const inc = path.join(SR, "include");
if (!fs.existsSync(path.join(inc, "stdio.h"))) {
  throw new Error("sysroot 里没有 include/stdio.h —— 拿到的是不完整的 sysroot，clang 一定编不了");
}

// ③ 真编一次 .so：这一条同时覆盖「找头文件」「链得出」「ABI 对」三层
const D = fs.mkdtempSync(path.join(os.tmpdir(), "lobos-clang-"));
try {
  fs.writeFileSync(path.join(D, "probe.c"),
    "int probe(void){ return 42; }\n");
  const so = path.join(D, "libprobe.so");
  const c = cp.spawnSync("clang", ["--sysroot=" + SR, "-shared", "-fPIC", "-O2",
                             "-o", so, path.join(D, "probe.c")],
    { encoding: "utf8", timeout: 120000 });
  if (c.status !== 0) {
    throw new Error("clang 编译失败（它可能找到了 clang 但找不到 sysroot，或工具链不全）: "
      + ((c.stderr || c.stdout || "").slice(0, 500)));
  }
  if (!fs.existsSync(so) || fs.statSync(so).size < 100) {
    throw new Error("clang 报成功但没产出 libprobe.so（或产物过小）");
  }
  // 产物必须是 aarch64 ELF —— 编成宿主 x86_64 是最容易错也最难发现的一处
  const head = Buffer.alloc(20);
  const fd = fs.openSync(so, "r");
  fs.readSync(fd, head, 0, 20, 0); fs.closeSync(fd);
  if (!(head[0] === 0x7f && head[1] === 0x45 && head[2] === 0x4c && head[3] === 0x46))
    throw new Error("产物不是 ELF（前四字节不是 \\x7fELF）");
  const is64 = head[4] === 2;
  if (!is64) throw new Error("产物不是 64 位 ELF");
  // e_machine 在偏移 18（16 位小端）：0xB7 = 183 = AArch64
  const machine = head.readUInt16LE(18);
  if (machine !== 0xB7)
    throw new Error("产物的 e_machine=" + machine + "（0xB7 才是 AArch64）—— 它编成了别的架构");

  // ④ 工具链其余成员也要能跑（不是只有 clang 能用）
  for (const [tool, arg] of [["ld.lld", "--version"], ["llvm-ar", "--version"],
                             ["llvm-strip", "--version"], ["llvm-nm", "--version"]]) {
    const x = cp.spawnSync(tool, [arg], { encoding: "utf8", timeout: 30000 });
    if (x.status !== 0) throw new Error(tool + " 起不来: status=" + x.status +
      " stderr=" + (x.stderr||"").slice(0,150));
  }

  console.log("clang ok: " + ver.split("\n")[0] + " · 真编出 aarch64 .so（" + fs.statSync(so).size + " 字节）· ld.lld/llvm-ar/llvm-nm/llvm-strip 各自可跑");
} finally {
  fs.rmSync(D, { recursive: true, force: true });
}
